// 3. Título branco 800 itálico maiúsculas (anim.text)
// 4. Grelha 2x2 de fotografias (src, src2..src4 ou srcs) que entram em cortina, com zoom lento
import React from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, spring } from "remotion";
import { loadFont } from "@remotion/google-fonts/Poppins";
import type { PrimitiveProps } from "../primitives";

loadFont("normal", { weights: ["600", "700", "800"], subsets: ["latin", "latin-ext"] });
const { fontFamily: POPPINS } = loadFont("italic", { weights: ["800"], subsets: ["latin", "latin-ext"] });

const PRIMARY = "#05B8E6";
const INK = "#213D56";
const WHITE = "#FFFFFF";
const TILE =["#B4B7B8", "#C4C7C8", "#C4C7C8", "#B4B7B8"];
const CLAMP = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

// Each tile wipes in from its own outer edge: left, top, bottom, right.
const WIPES = [
  (h: number) => `inset(0 ${h}% 0 0)`,
  (h: number) => `inset(0 0 ${h}% 0)`,
  (h: number) => `inset(${h}% 0 0 0)`,
  (h: number) => `inset(0 0 0 ${h}%)`,
];

const GrelhaQuatroImagens: React.FC<PrimitiveProps> = ({ anim, fps, frame }) => {
  const f = useCurrentFrame();
  const params = (anim.params ?? {}) as Record<string, unknown>;
  const str = (k: string): string => (params[k] == null ? "" : String(params[k]).trim());
  // `src` is the pipeline's slot; src2..src4 (or a srcs array) carry the rest.
  const list = Array.isArray(params.srcs) ? (params.srcs as unknown[]) : [];
  const srcs = [0, 1, 2, 3].map((i) => String((i === 0 ? params.src : params[`src${i + 1}`]) || list[i] || ""));
  const text = String(anim.text ?? "").trim();
  const location = str("location");

  // Laid out on a 540×960 stage, scaled to fit and centred.
  const W = frame.width;
  const H = frame.height;
  const u = Math.min(W / 540, H / 960);
  const len = Math.max(1, Math.round((anim.end - anim.start) * fps));
  const exitStart = Math.max(0, len - Math.round(fps * 0.35));
  const out = interpolate(f, [exitStart, Math.max(exitStart + 1, len)], [1, 0], CLAMP);
  const zoom = interpolate(f, [0, len], [1.12, 1], CLAMP);
  const head = spring({ frame: f - 8, fps, config: { damping: 18, stiffness: 150 } });
  const titleSize = 42 * u * Math.min(1, Math.sqrt(26 / Math.max(26, text.length)));

  return (
    <AbsoluteFill style={{ background: PRIMARY, fontFamily: POPPINS, color: WHITE, opacity: out, alignItems: "center", justifyContent: "center" }}>
      <div
        style={{
          width: 540 * u,
          height: 960 * u,
          boxSizing: "border-box",
          padding: `${64 * u}px ${32 * u}px ${40 * u}px`,
          display: "flex",
          flexDirection: "column",
          gap: 24 * u,
        }}
      >
        {text || location ? (
          <div style={{ display: "flex", flexDirection: "column", gap: 8 * u, opacity: head, transform: `translateY(${(1 - head) * 24 * u}px)` }}>
            {location ? (
              <div style={{ fontSize: 13 * u, fontWeight: 600, letterSpacing: 2 * u, color: INK, textTransform: "uppercase" }}>{location}</div>
            ) : null}
            {text ? (
              <div style={{ fontSize: titleSize, fontWeight: 800, fontStyle: "italic", lineHeight: 0.98, textTransform: "uppercase", overflowWrap: "break-word" }}>
                {text}
              </div>
            ) : null}
          </div>
        ) : null}
        <div
          style={{
            flexGrow: 1,
            display: "grid",
            gridTemplateColumns: "1fr 1fr",
            gridTemplateRows: "1fr 1fr",
            gap: 10 * u,
          }}
        >
          {srcs.map((s, i) => {
            const p = spring({ frame: f - i * 5, fps, config: { damping: 200 }, durationInFrames: 18 });
            return (
              <div key={i} style={{ position: "relative", overflow: "hidden", background: TILE[i], clipPath: WIPES[i]((1 - p) * 100) }}>
                {s ? <Img src={s} style={{ width: "100%", height: "100%", objectFit: "cover", transform: `scale(${zoom})` }} /> : null}
              </div>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default GrelhaQuatroImagens;

