import React from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, spring } from "remotion";
import { COLORS, FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const CLAMP = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

// Each tile wipes in from its own outer edge: left, top, bottom, right.
const WIPES = [
  (h: number) => `inset(0 ${h}% 0 0)`,
  (h: number) => `inset(0 0 ${h}% 0)`,
  (h: number) => `inset(${h}% 0 0 0)`,
  (h: number) => `inset(0 0 0 ${h}%)`,
];

const GrelhaQuatroImagens: React.FC<PrimitiveProps> = ({ anim, fps, format, frame }) => {
  const f = useCurrentFrame();
  const params = (anim.params ?? {}) as Record<string, unknown>;
  // `src` is the pipeline's slot; src2..src4 (or a srcs array) carry the rest.
  const src = String(anim.params?.src ?? "");
  const list = Array.isArray(params.srcs) ? (params.srcs as unknown[]) : [];
  const srcs = [0, 1, 2, 3].map((i) => {
    const v = i === 0 ? src : params[`src${i + 1}`];
    return String(v || list[i] || "");
  });
  const text = String(anim.text ?? "").trim();

  const len = Math.max(1, Math.round((anim.end - anim.start) * fps));
  const short = Math.min(frame.width, frame.height);
  const padX = Math.round(short * 0.067);
  const padY = format === "portrait" ? Math.round(frame.height * 0.12) : padX;
  const gap = Math.round(short * 0.016);

  const exitStart = Math.max(0, len - Math.round(fps * 0.35));
  const out = interpolate(f, [exitStart, Math.max(exitStart + 1, len)], [1, 0], CLAMP);
  const zoom = interpolate(f, [0, len], [1.12, 1], CLAMP);

  const cap = spring({ frame: f - 14, fps, config: { damping: 14, stiffness: 160 } });
  const fontSize = Math.round(
    short * (format === "portrait" ? 0.056 : 0.06) * Math.min(1, Math.sqrt(24 / Math.max(24, text.length))),
  );

  return (
    <AbsoluteFill style={{ fontFamily: FONTS.display, opacity: out }}>
      <div
        style={{
          position: "absolute",
          left: padX,
          right: padX,
          top: padY,
          bottom: padY,
          display: "grid",
          gridTemplateColumns: "1fr 1fr",
          gridTemplateRows: "1fr 1fr",
          gap,
        }}
      >
        {srcs.map((s, i) => {
          const p = spring({ frame: f - i * 5, fps, config: { damping: 200 }, durationInFrames: 18 });
          return (
            <div
              key={i}
              style={{
                position: "relative",
                overflow: "hidden",
                backgroundColor: COLORS.vellum,
                clipPath: WIPES[i]((1 - p) * 100),
              }}
            >
              {s ? (
                <Img
                  src={s}
                  style={{ width: "100%", height: "100%", objectFit: "cover", transform: `scale(${zoom})` }}
                />
              ) : (
                <div
                  style={{
                    position: "absolute",
                    left: "-20%",
                    right: "-20%",
                    top: "44%",
                    height: "12%",
                    backgroundColor: `${COLORS.teal}33`,
                    transform: "rotate(-11deg)",
                  }}
                />
              )}
            </div>
          );
        })}
      </div>
      {text ? (
        <AbsoluteFill style={{ justifyContent: "center", alignItems: "center" }}>
          <div
            style={{
              maxWidth: "78%",
              padding: `${Math.round(fontSize * 0.4)}px ${Math.round(fontSize * 0.9)}px`,
              borderRadius: 9999,
              backgroundColor: COLORS.teal,
              color: "rgba(255,255,255,1)",
              fontSize,
              fontWeight: FONTS.displayWeight,
              fontStyle: "italic",
              textTransform: "uppercase",
              lineHeight: 1.05,
              textAlign: "center",
              overflowWrap: "break-word",
              opacity: Math.min(1, Math.max(0, cap)),
              transform: `scale(${interpolate(cap, [0, 1], [0.6, 1])})`,
            }}
          >
            {text}
          </div>
        </AbsoluteFill>
      ) : null}
    </AbsoluteFill>
  );
};

export default GrelhaQuatroImagens;

